// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarmimport timber.log.Timberimport android.app.AlarmManagerimport android.content.Contextimport android.content.Intentimport android.net.Uriimport android.os.Buildimport android.provider.Settingsimport androidx.core.content.ContextCompat/** * NOUS — Alarm Permissions Helper (Module 14 v1.2 — Step 14.1). * * REAL implementation of alarm permission checking + requesting, * per strategy v1.2 §"Polish 3: Android 14 Exact Alarm Permission". * * ## Permission Matrix * * | API Level | Permission | How to Request | * |-----------|-----------|----------------| * | < 31 (Android 12) | None needed | N/A | * | 31-33 (Android 12-13) | SCHEDULE_EXACT_ALARM | Settings page (ACTION_REQUEST_SCHEDULE_EXACT_ALARM) | * | 34+ (Android 14+) | SCHEDULE_EXACT_ALARM or USE_EXACT_ALARM | Settings page or runtime dialog | * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 3</a> */class AlarmPermissionsHelper(    private val context: Context,) {    companion object {        private const val TAG = "AlarmPermissions"    }    /**     * Check if SCHEDULE_EXACT_ALARM is granted (REAL API 31+ check).     *     * Pre-API 31: always allowed (returns true).     * API 31+: checks `AlarmManager.canScheduleExactAlarms()` (instance method     * on the system [AlarmManager] obtained via [ContextCompat.getSystemService]).     */    fun canScheduleExactAlarms(): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) return true        val alarmManager = ContextCompat.getSystemService(context, AlarmManager::class.java)            ?: return false        return alarmManager.canScheduleExactAlarms()    }    /**     * Check if USE_EXACT_ALARM is granted (REAL API 34+ check).     *     * USE_EXACT_ALARM is a normal runtime permission on API 34+.     * Only granted to apps where exact alarms are core functionality.     * For NOUS, alarms/timers ARE core → we qualify.     */    fun hasUseExactAlarmPermission(): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) return false        return ContextCompat.checkSelfPermission(            context,            "android.permission.USE_EXACT_ALARM",        ) == android.content.pm.PackageManager.PERMISSION_GRANTED    }    /**     * Full permission check: either SCHEDULE_EXACT_ALARM OR USE_EXACT_ALARM.     *     * If either is granted, we can set exact alarms.     */    fun canSetExactAlarms(): Boolean {        return canScheduleExactAlarms() || hasUseExactAlarmPermission()    }    /**     * Launch the system settings page to request SCHEDULE_EXACT_ALARM (REAL API 31+).     *     * On API 34+ (Android 14), this is the ONLY way to request SCHEDULE_EXACT_ALARM.     * The user must manually toggle it in Settings.     *     * @param activity the current Activity (for launching Settings intent).     * @return true if the Settings page was launched successfully.     */    fun requestExactAlarmPermission(activity: android.app.Activity): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) return true        if (canScheduleExactAlarms()) return true        return try {            val intent = Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM).apply {                data = Uri.parse("package:${context.packageName}")                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            }            activity.startActivity(intent)            Timber.tag(TAG).i("Launched SCHEDULE_EXACT_ALARM settings page.")            true        } catch (e: Exception) {            Timber.tag(TAG).w("Could not launch SCHEDULE_EXACT_ALARM settings.", e)            false        }    }    /**     * Check if POST_NOTIFICATIONS is granted (REAL API 33+ check).     *     * Required for showing alarm/timer/reminder notifications on Android 13+.     */    fun canPostNotifications(): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return true        return ContextCompat.checkSelfPermission(            context,            android.Manifest.permission.POST_NOTIFICATIONS,        ) == android.content.pm.PackageManager.PERMISSION_GRANTED    }    /**     * Get the list of missing permissions for alarm/timer operations.     *     * @return list of missing permission strings (empty if all granted).     */    fun getMissingPermissions(): List<String> {        val missing = mutableListOf<String>()        if (!canSetExactAlarms()) {            // SCHEDULE_EXACT_ALARM is requested via Settings, not runtime.            // But we still list it so the UI can guide the user.            missing.add("android.permission.SCHEDULE_EXACT_ALARM")        }        if (!canPostNotifications()) {            missing.add(android.Manifest.permission.POST_NOTIFICATIONS)        }        return missing    }    /**     * Get a user-friendly message about missing permissions.     */    fun getMissingPermissionsMessage(): String {        val missing = getMissingPermissions()        if (missing.isEmpty()) return ""        return buildString {            if ("android.permission.SCHEDULE_EXACT_ALARM" in missing) {                append("I need exact alarm permission to set alarms at the right time. ")                append("Please enable it in Settings. ")            }            if (android.Manifest.permission.POST_NOTIFICATIONS in missing) {                append("I also need notification permission to show you when the alarm fires. ")            }        }.trim()    }}